ALTER TABLE public.visitor_sessions ADD COLUMN IF NOT EXISTS events jsonb NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE public.featured_events ADD COLUMN IF NOT EXISTS sport text, ADD COLUMN IF NOT EXISTS home_team text, ADD COLUMN IF NOT EXISTS away_team text, ADD COLUMN IF NOT EXISTS home_flag text, ADD COLUMN IF NOT EXISTS away_flag text, ADD COLUMN IF NOT EXISTS timer_mode text NOT NULL DEFAULT 'none', ADD COLUMN IF NOT EXISTS timer_target_at timestamptz;
CREATE TABLE public.downloadable_titles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL, tmdb_id text, title text NOT NULL, season integer, episode integer, storage_path text NOT NULL UNIQUE, size_bytes bigint NOT NULL DEFAULT 0, mime text NOT NULL DEFAULT 'video/mp4', poster_url text, description text, duration_seconds integer, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.downloadable_titles TO anon, authenticated; GRANT ALL ON public.downloadable_titles TO service_role;
ALTER TABLE public.downloadable_titles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public download catalogue" ON public.downloadable_titles FOR SELECT USING (true);
CREATE TABLE public.user_downloads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, title_id uuid NOT NULL REFERENCES public.downloadable_titles(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'queued', bytes_downloaded bigint NOT NULL DEFAULT 0, device_label text, started_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,title_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.user_downloads TO authenticated; GRANT ALL ON public.user_downloads TO service_role;
ALTER TABLE public.user_downloads ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owner downloads" ON public.user_downloads FOR ALL TO authenticated USING (auth.uid()=user_id) WITH CHECK (auth.uid()=user_id);
CREATE TABLE public.admin_broadcasts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL, message text NOT NULL, target_name text, target_session_key text, image_url text, image_path text, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.admin_broadcasts TO anon, authenticated; GRANT ALL ON public.admin_broadcasts TO service_role;
ALTER TABLE public.admin_broadcasts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Active broadcasts" ON public.admin_broadcasts FOR SELECT USING (active);
CREATE TABLE public.admin_broadcast_responses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), broadcast_id uuid NOT NULL REFERENCES public.admin_broadcasts(id) ON DELETE CASCADE, session_key text NOT NULL, name text, response_text text, rating integer CHECK(rating BETWEEN 1 AND 5), dismissed boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(broadcast_id,session_key));
GRANT ALL ON public.admin_broadcast_responses TO service_role;
ALTER TABLE public.admin_broadcast_responses ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.admin_changelog (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL DEFAULT 'new', title text NOT NULL, detail text, image_url text, image_path text, active boolean NOT NULL DEFAULT true, published_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.admin_changelog TO anon, authenticated; GRANT ALL ON public.admin_changelog TO service_role;
ALTER TABLE public.admin_changelog ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Active changelog" ON public.admin_changelog FOR SELECT USING(active);
CREATE TABLE public.analytics_daily_rollup(day date PRIMARY KEY, visits integer NOT NULL DEFAULT 0, minutes integer NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.analytics_daily_rollup TO service_role; ALTER TABLE public.analytics_daily_rollup ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.api_keys(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), key text NOT NULL UNIQUE, label text NOT NULL DEFAULT 'Untitled key', owner_name text, rate_limit_per_hour integer NOT NULL DEFAULT 1000, request_count integer NOT NULL DEFAULT 0, active boolean NOT NULL DEFAULT true, last_used_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.api_keys TO service_role; ALTER TABLE public.api_keys ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.api_endpoints(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE, description text, upstream_url text NOT NULL, upstream_header_name text, upstream_header_value text, request_count integer NOT NULL DEFAULT 0, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.api_endpoints TO service_role; ALTER TABLE public.api_endpoints ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.api_request_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), path text NOT NULL, status integer, api_key text, api_key_id uuid REFERENCES public.api_keys(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.api_request_logs TO service_role; ALTER TABLE public.api_request_logs ENABLE ROW LEVEL SECURITY;